func TestParseResolvConf(t *testing.T) {
	fixture := `
# Generated by NetworkManager
nameserver 1.1.1.1
nameserver 8.8.8.8
nameserver 1.1.1.1 # duplicate
nameserver invalid.ip
# nameserver 9.9.9.9
nameserver 2606:4700:4700::1111
`
	expected := []string{"1.1.1.1", "8.8.8.8", "2606:4700:4700::1111"}
	got := parseResolvConf(fixture)
	if !reflect.DeepEqual(got, expected) {
		t.Fatalf("parseResolvConf = %v; want %v", got, expected)
	}
}

